  ('book_003', 'book', 'uksssc-graduate-level-1500-mcqs', 'UKSSSC Graduate Level: 1500 Practice MCQs', 'Subject-wise practice sets modelled on the UKSSSC Graduate Level pattern, with answer keys and short explanations for every question.', 'sub_gs', ARRAY['exam_uksssc','exam_junior_assistant']::text[], 'Devbhoomi Prep Editorial Team', 'bilingual', 2025, 296, 'samples/sample-material.pdf', 'samples/sample-preview.pdf', '#166a42', 'original', true, true, true, 2290, 461, '2026-07-15T09:00:00.000Z'),
