  ('book_006', 'book', 'quantitative-aptitude-uttarakhand-exams', 'Quantitative Aptitude for Uttarakhand Exams', 'Arithmetic, percentages, ratio, time & work, speed-distance, mensuration and data interpretation with shortcut methods and 1200 solved problems.', 'sub_math', ARRAY['exam_uksssc','exam_police','exam_patwari','exam_forest_guard']::text[], 'Devbhoomi Prep Editorial Team', 'bilingual', 2025, 360, 'samples/sample-material.pdf', 'samples/sample-preview.pdf', '#23905c', 'original', true, true, false, 3345, 675, '2026-06-12T09:00:00.000Z'),
