  ('ann_trial_banner', 'banner', 'Start your 30-day free trial', 'New students get 30 days of full access to books, notes, previous-year papers and mock tests. No card required.', '/signup', 'Start Free Trial', true, '2026-08-02T09:00:00.000Z', '2027-02-28T09:00:00.000Z', '2026-08-02T09:00:00.000Z'),
